public sealed partial class DemoWorld {
 public AdvancedStateH Advanced{get;set;}=new();
 public bool InHubH=>SystemId=="system:30100000";
 public bool InTriuneH=>ImportedWorld43&&Galaxy42.ById.GetValueOrDefault(int.Parse(SystemId[7..]))?.RegionId==10000070;
 public void JournalH(string message){Advanced.Journal.Add(Now.ToString("u")+" / "+message);if(Advanced.Journal.Count>200)Advanced.Journal.RemoveAt(0);}
 public void EnsureAdvancedH(){EnsurePopulationC();if(!Advanced.Influence.ContainsKey(SystemId))Advanced.Influence[SystemId]=100;if(!Organisations.Territories.Any(t=>t.System==SystemId))Organisations.Territories.Add(new(){System=SystemId});if(!Advanced.Campaigns.Any(c=>c.System==SystemId))Advanced.Campaigns.Add(new(){System=SystemId,Station=EncounterIssuerF(),Ends=Now.AddDays(7)});}
 public string IssueAdvancedH(string template,string den="") {
  EnsureAdvancedH();if(!AdvancedCatalogH.Encounters.Any(d=>d.Id==template))return "Unknown advanced operation.";
  if(template is "h_mto" or "h_defence")return "Use the den opportunity board.";
  if(template=="h_flashpoint"&&(!InTriuneH||Advanced.RegionalStanding<1))return "Travel to the Triune region and earn one standing point.";
  if(Advanced.Operations.Any(o=>o.Kind==template&&Exploration.Encounters.Any(e=>e.Id==o.Encounter&&e.System==SystemId&&e.State is "Available" or "Active")))return "An unfinished operation already exists here.";
  int influence=Advanced.Influence[SystemId];if(template=="h_scout"&&influence!=100||template=="h_vanguard"&&influence!=65||template=="h_mothership"&&influence!=30)return "Resolve the preceding regional threat stage first.";
  if(Balance<100)return "100 CR deployment fee required.";WalletChange(-100,"Advanced operation deployment");CreateAdvancedH(template,den);return "";
 }
 EncounterF CreateAdvancedH(string template,string den=""){var e=AddEncounterF(template,SystemId,true);decimal crewBudget=AdvancedCatalogH.Roles(template).Length>0?e.Reward*.4m:0;e.Reward-=crewBudget;Advanced.Operations.Add(new(){Encounter=e.Id,Kind=template,Den=den,CrewBudget=crewBudget});JournalH("Issued / "+EncounterCatalogF.Get(template).Name);return e;}
 public bool EnterGuardH(EncounterF e){if(!e.Template.StartsWith("h_"))return true;var op=Advanced.Operations.FirstOrDefault(o=>o.Encounter==e.Id);if(op==null)return false;
  if(e.State=="Completed")return true;
  if(e.Template=="h_flashpoint"&&(!InTriuneH||Advanced.RegionalStanding<1)){Say("Regional access required.");return false;}
  if(e.Template=="h_mto"&&!CruiserEligibleF){Say("This intelligence operation requires a cruiser.");return false;}
  foreach(string role in AdvancedCatalogH.Roles(e.Template))if(!Population.Pilots.Any(p=>p.Contracted&&!p.Suspended&&p.Status!="Lost"&&p.Order!="Hold"&&p.Role==role)){Say("Missing paid active fleet role / "+role);return false;}
  if(op.Den!=""&&!Advanced.Dens.Any(d=>d.Id==op.Den&&d.System==SystemId&&d.State is "Online" or "Under attack")){Say("The owning den is no longer available.");return false;}
  return true;
 }
 public void BindCrewH(EncounterF e){if(!e.Template.StartsWith("h_"))return;var operation=Advanced.Operations.FirstOrDefault(o=>o.Encounter==e.Id);if(operation!=null&&operation.Crew.Count==0&&e.State=="Active")operation.Crew=Population.Pilots.Where(p=>p.Contracted&&!p.Suspended&&p.Status!="Lost"&&p.Order!="Hold").Select(p=>p.Id).ToList();var enemy=Targets.FirstOrDefault(t=>t.Kind==TargetKind.Raider&&!t.Friendly&&!t.Destroyed);var rock=Targets.FirstOrDefault(t=>t.Id.Contains(":ore:"));foreach(var p in Population.Pilots.Where(p=>p.Contracted&&!p.Suspended&&p.Order!="Hold"&&p.Role=="Miner")){if(rock!=null){p.Target=rock.Id;p.Order="Mine";var target=Targets.FirstOrDefault(t=>t.Id==p.Id);if(target!=null&&Vector3.Distance(target.Position,rock.Position)<p.Fit.Stat("maxTargetRange"))p.Knowledge[rock.Id]=Now.AddSeconds(20);}}if(enemy==null)return;foreach(var p in Population.Pilots.Where(p=>p.Contracted&&!p.Suspended&&p.Order!="Hold"&&p.Role is "Escort" or "Tackler")){p.Order="Attack";p.Target=enemy.Id;} }
 public void CompleteAdvancedH(EncounterF e){var op=Advanced.Operations.FirstOrDefault(o=>o.Encounter==e.Id);if(op==null||op.Applied)return;op.Applied=true;
  if(e.Template is "h_scout" or "h_vanguard" or "h_mothership"){int expected=e.Template=="h_scout"?100:e.Template=="h_vanguard"?65:30;if(Advanced.Influence.GetValueOrDefault(e.System)==expected)Advanced.Influence[e.System]=e.Template=="h_scout"?65:e.Template=="h_vanguard"?30:0;}
  if(e.Template=="h_flashpoint")Advanced.RegionalStanding=Math.Min(10,Advanced.RegionalStanding+1);
  var den=Advanced.Dens.FirstOrDefault(d=>d.Id==op.Den);if(den!=null&&den.State!="Destroyed"){if(e.Template=="h_mto"){den.Development=Math.Min(10,den.Development+1);den.Anarchy=Math.Max(0,den.Anarchy-2);}if(e.Template=="h_defence")den.State="Online";}
  foreach(var c in Advanced.Campaigns.Where(c=>c.System==e.System&&c.State=="Active"&&c.Ends>Now))if(c.Events.Add(e.Id)){if(c.Choice=="Support")c.Support=Math.Min(100,c.Support+25);if(c.Choice=="Oppose")c.Oppose=Math.Min(100,c.Oppose+25);if(c.Choice=="Independent")c.Independent=Math.Min(100,c.Independent+25);}
  JournalH("Objective recorded once / "+e.Id);
 }
 public void SettleCrewH(EncounterF e){var op=Advanced.Operations.FirstOrDefault(o=>o.Encounter==e.Id);if(op==null||op.Settled)return;op.Settled=true;var crew=Population.Pilots.Where(p=>op.Crew.Contains(p.Id)).ToArray();if(crew.Length>0){decimal each=op.CrewBudget/crew.Length;foreach(var p in crew){p.Wallet+=each;Population.ExternalNet+=each;}}JournalH("Settlement / player "+e.Reward+" / crew budget "+op.CrewBudget+" / crew "+crew.Length+" / losses "+crew.Count(p=>p.Status=="Lost"));}
 public string DeployDenH(){if(!Docked||InHubH||Advanced.Dens.Any(d=>d.System==SystemId&&d.State!="Destroyed")||Balance<2000||Hangar.GetValueOrDefault("ore")<100)return "Dock outside the restricted hub with 2,000 CR and 100 ore; one active den per system.";WalletChange(-2000,"Mercenary den deployment");Hangar["ore"]-=100;Advanced.Dens.Add(new(){System=SystemId,Station=StationKey44,Due=Now.AddHours(1),Last=Now.AddHours(1),NextOpportunity=Now.AddHours(1)});JournalH("Den anchoring / one hour / actual ore and credits consumed");return "";}
 public string FuelDenH(string id){var d=Advanced.Dens.FirstOrDefault(d=>d.Id==id);if(d==null||!Docked||StationKey44!=d.Station||d.State=="Destroyed"||Hangar.GetValueOrDefault("ore")<100||d.Fuel>900)return "Owned local den and 100 ore required; capacity 1,000.";Hangar["ore"]-=100;d.Fuel+=100;return "";}
 public string ClaimDenH(string id){var d=Advanced.Dens.FirstOrDefault(d=>d.Id==id);if(d==null||!Docked||StationKey44!=d.Station||d.State!="Online"||d.Output==0)return "Unclaimed output at an online local den required.";Hangar["e_decryptor"]=Hangar.GetValueOrDefault("e_decryptor")+d.Output;JournalH("Den output claimed / "+d.Output+" authored decryption components");d.Output=0;return "";}
 public string OpportunityDenH(string id){var d=Advanced.Dens.FirstOrDefault(d=>d.Id==id);if(d==null||d.System!=SystemId||d.State!="Online"||d.NextOpportunity>Now||Balance<100)return "Online local den, expired cooldown and 100 CR required.";WalletChange(-100,"Den intelligence deployment");CreateAdvancedH("h_mto",d.Id);d.NextOpportunity=Now.AddHours(4);return "";}
 public string SetCampaignChoiceH(string choice){EnsureAdvancedH();var c=Advanced.Campaigns.First(c=>c.System==SystemId);if(c.State!="Active"||c.Ends<=Now||choice is not("Support" or "Oppose" or "Independent" or "Abstain"))return "An active campaign and valid voluntary choice required.";c.Choice=choice;return "";}
 public string DeliverCampaignH(){EnsureAdvancedH();var c=Advanced.Campaigns.First(c=>c.System==SystemId);if(!Docked||StationKey44!=c.Station||c.State!="Active"||c.Ends<=Now||c.Choice=="Abstain"||Hangar.GetValueOrDefault("ore")<100)return "Choose a path and deliver 100 real ore at the campaign contact before expiry.";int progress=c.Choice=="Support"?c.Support:c.Choice=="Oppose"?c.Oppose:c.Independent;if(progress>=100)return "Contribution cap reached.";Hangar["ore"]-=100;if(c.Choice=="Support")c.Support=Math.Min(100,c.Support+10);if(c.Choice=="Oppose")c.Oppose=Math.Min(100,c.Oppose+10);if(c.Choice=="Independent")c.Independent=Math.Min(100,c.Independent+10);return "";}
 public string BuyRegionalPassH(){if(!Docked||Balance<400)return "Dock with 400 CR.";int stock=Advanced.Stock.GetValueOrDefault(StationKey44,3);if(stock<=0)return "Finite local transit stock exhausted.";WalletChange(-400,"Regional transit kit");Advanced.Stock[StationKey44]=stock-1;Hangar["h_filament"]=Hangar.GetValueOrDefault("h_filament")+2;return "";}
 public string TravelTriuneH(bool exit){if(!ImportedWorld43)return "Use the imported universe for source region travel.";if(Docked||InWarp||Transit!=null||InAbyssF||Commander.Capsule||!CanUseGate("player")||Now<Advanced.FilamentReady||CargoItems.GetValueOrDefault("h_filament")<1||CombatHulls.Get(Player.CombatHull).Size>3)return "Undocked subcapital, one cargo filament, no tackle and elapsed 15-minute cooldown required.";
  if(exit&&(!InTriuneH||Advanced.ReturnSystem==""))return "No saved regional return route.";if(!exit&&(InTriuneH||InHubH))return "Entry begins outside the special regions.";
  string destination=exit?Advanced.ReturnSystem:"system:"+Galaxy42.ById.Values.Where(s=>s.RegionId==10000070).OrderBy(s=>s.Id).First().Id;if(!exit)Advanced.ReturnSystem=SystemId;CargoItems["h_filament"]--;Advanced.FilamentReady=Now.AddMinutes(15);SyncEncounterF();RecoverProbesForTransit();LeaveSupportGrid(true);SystemId=destination;EnterGrid("station",false);Player.Position=Vector3.Zero;Player.Velocity=Vector3.Zero;AdvanceHours(1d/3600);JournalH("Authored single-pilot filament transit / "+destination);return "";}
 public string EarnRegionalAccessH(){if(!InTriuneH||Docked||Advanced.RegionalStanding>=1)return "Regional border contact in space required; first access can be earned once.";if(CargoItems.GetValueOrDefault("ore")<100&&Player.Ore<100)return "Deliver 100 cargo ore to the independent regional contact.";if(Player.Ore>=100)Player.Ore-=100;else CargoItems["ore"]-=100;Advanced.RegionalStanding=1;JournalH("Regional contact supplied / basic flashpoint access earned");return "";}
 public string HubGateErrorH(string destination){if(!InHubH&&destination!="system:30100000")return "";if(CombatHulls.Get(Player.CombatHull).Size>3)return "Restricted hub accepts subcapital ships only in this candidate.";if(InHubH&&Now<Advanced.HubUnlock&&Advanced.HubOrigin!=""&&destination!=Advanced.HubOrigin)return "Emanation lock: use entry gate until "+Advanced.HubUnlock.ToString("u");return "";}
 public void HubGateEnteredH(string origin){if(InHubH){Advanced.HubOrigin=origin;Advanced.HubUnlock=Now.AddHours(6);JournalH("Restricted hub entry / six-hour emanation lock");}}
 public void AdvanceAdvancedH(){if(ActiveEncounterF is {State:"Active"} active&&active.Template.StartsWith("h_"))BindCrewH(active);
  foreach(var d in Advanced.Dens.Where(d=>d.State!="Destroyed")){if(d.State=="Anchoring"&&d.Due<=Now)d.State="Online";if(d.State=="Anchoring")continue;int hours=(int)Math.Max(0,(Now-d.Last).TotalHours);if(hours>0){d.Last=d.Last.AddHours(hours);int consumed=Math.Min(d.Fuel,hours);d.Fuel-=consumed;d.Output=Math.Min(500,d.Output+consumed*(1+d.Development));d.Anarchy=Math.Min(10,d.Anarchy+hours);if(d.Anarchy>=4&&d.State=="Online"){var e=AddEncounterF("h_defence",d.System,true);e.OriginStation=d.Station;Advanced.Operations.Add(new(){Encounter=e.Id,Kind="h_defence",Den=d.Id});d.Defence=e.Id;d.State="Under attack";JournalH("Den attack / protect controller before expiry");}}
   if(d.State=="Under attack"){var defence=Exploration.Encounters.FirstOrDefault(e=>e.Id==d.Defence);if(defence?.State is "Failed" or "Expired"){d.State="Destroyed";d.Fuel=0;d.Output=0;JournalH("Den destroyed / unclaimed output lost");}}
  }
  foreach(var c in Advanced.Campaigns.Where(c=>c.State=="Active"&&c.Ends<=Now)){c.State="Resolved";c.Outcome=c.Independent>Math.Max(c.Support,c.Oppose)?"Independent logistics":c.Support>c.Oppose?"Supported mobilisation":c.Oppose>c.Support?"Opposition held":"Unchanged / abstention or tie";EnsureOrganisationsG();var t=Organisations.Territories.FirstOrDefault(t=>t.System==c.System);if(t!=null){if(c.Outcome=="Supported mobilisation")t.Suppression=Math.Min(100,t.Suppression+25);if(c.Outcome=="Opposition held")t.Corruption=Math.Min(100,t.Corruption+25);if(c.Outcome=="Independent logistics"){Advanced.RegionalStanding=Math.Min(10,Advanced.RegionalStanding+1);t.Suppression=Math.Min(100,t.Suppression+10);}}JournalH("Campaign resolved / "+c.Outcome);}
 }
 public static void ValidateAdvancedLinksH(SaveData data){var a=data.Advanced;if(a==null)return;bool ValidSystem(string id)=>data.WorldDefinitionId==Spatial43.WorldId?Spatial43.IsSystem(id):Systems.Any(s=>s.Id==id);if(a.Influence.Keys.Any(id=>!ValidSystem(id))||a.Dens.Any(d=>!ValidSystem(d.System))||a.Campaigns.Any(c=>!ValidSystem(c.System))||a.Campaigns.Select(c=>c.Id).Distinct().Count()!=a.Campaigns.Count||a.Operations.Any(o=>!AdvancedCatalogH.Encounters.Any(t=>t.Id==o.Kind)||data.Exploration?.Encounters.Any(e=>e.Id==o.Encounter&&e.Template==o.Kind)!=true||o.Crew.Distinct().Count()!=o.Crew.Count||o.Crew.Any(id=>data.Population?.Pilots.Any(p=>p.Id==id)!=true)||o.Den!=""&&!a.Dens.Any(d=>d.Id==o.Den))||a.ReturnSystem!=""&&!ValidSystem(a.ReturnSystem)||a.HubOrigin!=""&&!new[]{"system:30001041","system:30001269","system:30002086","system:30003841"}.Contains(a.HubOrigin))throw new InvalidDataException("Advanced activities contain invalid world or actor references.");}
 public static void ValidateAdvancedH(AdvancedStateH? a){if(a==null)return;if(a.Operations==null||a.Dens==null||a.Campaigns==null||a.Influence==null||a.Stock==null||a.Journal==null||a.RegionalStanding<0||a.RegionalStanding>10||a.Operations.Any(o=>o.Crew==null||o.CrewBudget<0)||a.Operations.Select(o=>o.Encounter).Distinct().Count()!=a.Operations.Count||a.Dens.Select(d=>d.Id).Distinct().Count()!=a.Dens.Count||a.Dens.Any(d=>d.Fuel<0||d.Fuel>1000||d.Output<0||d.Output>500||d.Development<0||d.Development>10||d.Anarchy<0||d.Anarchy>10||d.State is not("Anchoring" or "Online" or "Under attack" or "Destroyed"))||a.Influence.Values.Any(v=>v is not(100 or 65 or 30 or 0))||a.Stock.Values.Any(v=>v<0||v>3)||a.Campaigns.Any(c=>c.Events==null||c.Support<0||c.Support>100||c.Oppose<0||c.Oppose>100||c.Independent<0||c.Independent>100||c.Choice is not("Support" or "Oppose" or "Independent" or "Abstain")||c.State is not("Active" or "Resolved")))throw new InvalidDataException("Invalid advanced activity state.");}
}
